// Some portions generated by Codex

const test = require('node:test');
const assert = require('node:assert/strict');
const { EventEmitter } = require('node:events');
const { createExploreNavigationTracker, unexpectedHttpErrorConsoleMessages }
    = require('../tests/workbench-browser-health');

const EXPLORE = 'http://localhost:8080/rdf4j-workbench/repositories/test/explore';

function sectionRequest(overrides = {}) {
    const url = new URL(EXPLORE);
    url.search = new URLSearchParams({
        resource: '<urn:resource>', section: 'outgoing', kind: 'rows',
        'query-request-id': 'explore-clock-old-1', ...overrides
    }).toString();
    return { url: url.href, method: 'GET', error: 'NS_BINDING_ABORTED' };
}

function observe(page, request) {
    page.emit('request', { method: () => request.method, url: () => request.url });
}

test('expected HTTP error console output is optional across browsers', () => {
    assert.deepEqual(unexpectedHttpErrorConsoleMessages([], 400), []);
    assert.deepEqual(unexpectedHttpErrorConsoleMessages([
        'Failed to load resource: the server responded with a status of 400 (Bad Request)'
    ], 400), []);
});

test('unexpected console errors and duplicate browser errors remain failures', () => {
    for (const messages of [
        ['TypeError: cannot read properties of undefined'],
        ['Failed to load resource: the server responded with a status of 500 (Server Error)'],
        ['Failed to load resource: the server responded with a status of 4000'],
        ['Failed to load resource: the server responded with a status of 400',
            'Failed to load resource: the server responded with a status of 400']
    ]) {
        assert.deepEqual(unexpectedHttpErrorConsoleMessages(messages, 400), messages);
    }
});

test('only an explicitly departing Explore controller can have expected aborts', () => {
    const page = new EventEmitter();
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    const request = sectionRequest();
    observe(page, request);
    assert.equal(tracker.recordFailure(request).expectedRouteAbort, false, 'current route stays strict');
    const earlyFailure = tracker.recordFailure(request);
    tracker.expectNavigation();
    assert.equal(earlyFailure.expectedRouteAbort, false, 'later navigation cannot forgive an active-route failure');
    for (const error of ['NS_BINDING_ABORTED', 'net::ERR_ABORTED', 'cancelled']) {
        assert.equal(tracker.recordFailure({ ...request, error }).expectedRouteAbort, true);
    }
    assert.equal(tracker.recordFailure({ ...request, error: 'NS_ERROR_FAILURE' }).expectedRouteAbort, false);
});

test('late queued requests belong to the old controller but same-resource revisits do not', () => {
    const page = new EventEmitter();
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    observe(page, sectionRequest());
    tracker.expectNavigation();
    const late = sectionRequest({ section: 'range', kind: 'count', 'query-request-id': 'explore-clock-old-29' });
    observe(page, late);
    assert.equal(tracker.recordFailure(late).expectedRouteAbort, true);
    const revisit = sectionRequest({ 'query-request-id': 'explore-clock-new-1' });
    observe(page, revisit);
    assert.equal(tracker.recordFailure(revisit).expectedRouteAbort, false);
    tracker.expectNavigation();
    assert.equal(tracker.recordFailure(revisit).expectedRouteAbort, true);
});

test('Back navigation cancels the blank-node controller without excusing the returning graph controller', () => {
    const page = new EventEmitter();
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    observe(page, sectionRequest({ resource: '<urn:graph>', 'query-request-id': 'explore-clock-graph-1' }));
    tracker.expectNavigation();

    const blank = sectionRequest({ resource: '<_:stored-node>', section: 'range', kind: 'count',
        'query-request-id': 'explore-clock-blank-29' });
    observe(page, blank);
    const beforeBack = tracker.recordFailure(blank);
    assert.equal(beforeBack.expectedRouteAbort, false, 'leaving the graph did not mark the blank-node controller');

    tracker.expectNavigation();
    assert.equal(tracker.recordFailure(blank).expectedRouteAbort, true,
        'Back explicitly marks the pending blank-node count request as departing');
    assert.equal(beforeBack.expectedRouteAbort, false, 'Back cannot forgive an earlier active-route failure');

    const returnedGraph = sectionRequest({ resource: '<urn:graph>', 'query-request-id': 'explore-clock-returned-1' });
    observe(page, returnedGraph);
    assert.equal(tracker.recordFailure(returnedGraph).expectedRouteAbort, false,
        'the fresh graph controller remains strict after Back');
});

test('scope includes origin, repository, canonical resource, method and section identity', () => {
    const page = new EventEmitter();
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    const original = sectionRequest();
    observe(page, original);
    tracker.expectNavigation();
    const otherOrigin = { ...original, url: original.url.replace('localhost', 'example.com') };
    const otherRepository = { ...original, url: original.url.replace('/test/', '/other/') };
    const malformed = { ...original, url: 'not a URL' };
    for (const request of [
        otherOrigin, otherRepository, malformed, { ...original, method: 'POST' },
        sectionRequest({ resource: '<urn:other>' }), sectionRequest({ section: '' }),
        sectionRequest({ section: 'unknown' }),
        sectionRequest({ kind: 'other' }), sectionRequest({ 'query-request-id': '' }),
        sectionRequest({ 'query-request-id': 'not-a-controller-id' })
    ]) {
        assert.equal(tracker.recordFailure(request).expectedRouteAbort, false, JSON.stringify(request));
    }
});

test('unobserved controllers are not admitted by an earlier navigation', () => {
    const page = new EventEmitter();
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    tracker.expectNavigation();
    const request = sectionRequest();
    observe(page, request);
    assert.equal(tracker.recordFailure(request).expectedRouteAbort, false);
});

test('request identity does not compare a QName page URL with its resolved resource', () => {
    const page = new EventEmitter();
    page.url = () => `${EXPLORE}?resource=ex%3Aresource`;
    const tracker = createExploreNavigationTracker(page, EXPLORE);
    const request = sectionRequest({ resource: '<http://example.org/resource>' });
    observe(page, request);
    assert.equal(tracker.recordFailure(request).expectedRouteAbort, false);
    tracker.expectNavigation();
    assert.equal(tracker.recordFailure(request).expectedRouteAbort, true);
});
